    console.assert(JSON.stringify(candidate([1,2,3,4,5], 1, 2)) === JSON.stringify([0, 1, 2]));
    console.assert(JSON.stringify(candidate([2,2,2,2,2], 2, 2)) === JSON.stringify([0, 1, 2, 3, 4]));
    console.assert(JSON.stringify(candidate([1,2,3,4,5], 5, 2)) === JSON.stringify([2, 3, 4]));
